#!/usr/bin/env bash
# Re-runs every tool step of this Phase 2 run from the inputs, in stage order.
# The judgement steps (S3 plan, S5 RTL, S7 escalation, S4/S10 review records, S10 notes) were done
# by hand and are read as they are; everything else is regenerated by a tool.
set -euo pipefail
cd "$(dirname "$0")"
export PATH=/tmp/verible-v0.0-3946-g851d3ff4/bin:$PATH   # adjust to your Verible install
H=S1_intake/run2_answered/phase1_handoff.json

# S1 + S2, run 1: the original Phase 1 output (expected: blocked)
python3 tools/s1_normalize.py inputs/phase1_original S1_intake/run1_original
python3 tools/s2_readiness.py S1_intake/run1_original/phase1_handoff.json S2_readiness/run1_original || true
# S1 + S2, run 2: Phase 1's answers
python3 tools/s1_normalize.py inputs/phase1_answered S1_intake/run2_answered
python3 tools/s2_readiness.py $H S2_readiness/run2_answered --approvals inputs/decision_approvals.json

# S3 self-check and S4 for plan v1 and v2
for v in 1 2; do
  python3 tools/check_plan.py $H S3_plan/design_plan_v$v.json S3_plan
  python3 tools/s4_review.py $H S3_plan/design_plan_v$v.json S3_plan/plan_v${v}_validation.json S4_review
done
python3 tools/s4_review.py $H S3_plan/design_plan_v2.json S3_plan/plan_v2_validation.json S4_review S4_review/plan_v2_review.json

# S6 on the final RTL (round 2), S8, S9, S10 manifest
python3 tools/s6_gate.py S5_rtl S4_review/design_plan_approved.json S6_gate/round2
python3 tools/s8_smoke.py $H S5_rtl S8_smoke
python3 tools/s9_trace.py $H S4_review/design_plan_approved.json S5_rtl S6_gate/round2/design.xml S9_trace
python3 tools/s10_manifest.py .
